/**
 * Always-injected orientation per connector: gates, owner-phrase map, grains,
 * name resolution, population map, cross-cutting traps, hard limits.
 */
export const CONNECTOR_PLAYBOOK_CORES: Readonly<Record<string, string>> = Object.freeze({
  "lightspeed-r": "# Lightspeed Retail (R-Series) — how this shop's data actually reads\n\nYou are answering a shop owner. They speak shop. Lightspeed speaks sales, sale lines,\nitems, categories, workorders, orders. This page is the bridge: what the owner's words\nusually mean, which table honestly answers them, and which correct-looking query is\ncommercially wrong. The table index tells you what exists; the dimension guide gives\nthe deep rules for the current question's territory.\n\nLightspeed is **operational truth**: what was rung up, what is on the shelf, what is on\nthe workshop board, who bought it. Xero is **financial truth**: invoices, bills, GST,\nbank. They share no ids. Never join across them; answer from one and say which.\n\nEverything lives in `source_lightspeed.*` and every queryable table starts with `ls_`.\nThe schema also contains retired unprefixed tables (`sales`, `items`, `customers`, …)\nfrom an earlier pipeline — they are **empty** and the SQL service rejects them. Ninety\n`ls_` tables, one shop's whole operation. Most questions land on about eight of them.\n\n---\n\n## 1. Three gates before any number\n\n**Gate 1 — `tombstone = false`.** Always, unless the owner asked about deleted records.\n\n**Gate 2 — one pack generation only.** Staging holds rows from two connector pack\ngenerations side by side (`mapping_version`). Where they overlap, every record is\npresent **twice**, and a plain `COUNT(*)` or `SUM()` silently doubles it. Verified live:\n`ls_categories` holds 158 rows for 79 real categories; `ls_item_shops` holds 64,010 rows\nfor 34,010 real stock records.\n\nResolve the current generation **by ingest recency**, once, and reuse it:\n\n```sql\nWITH pack AS (\n  SELECT mapping_version AS mv\n  FROM source_lightspeed.ls_sales\n  GROUP BY 1 ORDER BY max(ingested_at) DESC LIMIT 1\n)\n```\n\nToday that resolves to `'2.0.0'`; the retired one is `'m2-v1'`. **Do not use\n`max(mapping_version)`** — these are text, and `'m2-v1'` sorts above `'2.0.0'`, so the\nlexical maximum silently pins the *old, partial* generation and every figure comes back\ntoo small while looking entirely plausible.\n\nApply the pin on **every** `source_lightspeed` table in the query, including lookup\njoins — an un-pinned join to `ls_categories` fans every product row out twofold. If a\ncount comes back at a suspiciously round multiple, or a full-history question returns\nonly recent weeks, this gate is why.\n\n**Gate 3 — money means completed and not voided.** On `ls_sales`:\n`completed = true AND voided = false`. Open tickets carry full totals and no payments;\nvoided tickets keep their money columns fully populated. Missing either filter inflates\nrevenue. `archived` is **not** voided — an archived completed sale was real revenue,\nkeep it.\n\n---\n\n## 2. What the owner is really asking\n\n| They say | They usually mean | Start here |\n|---|---|---|\n| \"how did we go last month\", \"takings\", \"turnover\" | ticket-level revenue | `ls_sales`, `SUM(calc_total)` |\n| \"did we sell any X\", \"how are X going\" | a **product type**, not one SKU | category tree → `ls_sale_lines` |\n| \"how many of the *Marathon Plus*\" | one SKU | resolve to `item_id`, then `ls_sale_lines` |\n| \"gen services\", \"brake bleeds\" | one named service item | resolve to `item_id` (service items, §4) |\n| \"how's the workshop going\" | service revenue, not the job board | `ls_sale_lines.is_workorder = true` |\n| \"what's on the board\", \"how many jobs open\" | the job board | `ls_workorders` — **but see §5, it is near-empty** |\n| \"what's the cash\", \"did the till balance\" | tenders and drawer | `ls_sale_payments`, `ls_register_count_amounts` |\n| \"what have we got\", \"how much stock\" | on-hand right now | `ls_item_shops` (snapshot, no history) |\n| \"what's on order\" | supplier POs | `ls_purchase_orders` + `ls_purchase_order_lines` |\n| \"orders\" | **almost never** POs — they mean customer sales | `ls_sales` |\n| \"who's our best customer\" | identified customers only | `ls_customers` + sales; disclose walk-ins |\n| \"who sold the most\" | who rang the ticket | `ls_sales.employee_id` |\n| \"what did we make on it\" | margin | `calc_total - calc_tax1 - calc_tax2 - calc_fifo_cost` |\n\nThree habits worth keeping:\n\n- **Decide the grain before you resolve the name.** \"Any glasses sold\" is a category\n  question; \"how did the Lupo go\" is a SKU question. Resolving first and then letting\n  the top match choose the grain is how a plural question gets a single-SKU answer.\n- **A plural noun is a hint, not proof.** \"Helmets\" is a category. \"The helmet I\n  ordered in\" is one item. Read the sentence, not the ending.\n- **A \"report\" is layered.** Whatever the subject, a report request means: the\n  headline summary cut, then the ranked detail that names real items, people or\n  categories with quantities and dollar values, then — when it adds insight — one more\n  split or trend. One summary table answers a question; it does not constitute a\n  report. Methodology is yours to choose from these pages and disclose, never to ask\n  about.\n\n---\n\n## 3. Five grains, one honest table each\n\n| Grain | Table | Honest for | Never for |\n|---|---|---|---|\n| Ticket | `ls_sales` | revenue, ticket counts, basket, staff attribution | per-product anything |\n| Line | `ls_sale_lines` | units, rankings, per-item revenue | state/date filters (join `ls_sales`) |\n| Tender | `ls_sale_payments` | takings, cash movement, tender mix | revenue recognition |\n| Stock snapshot | `ls_item_shops` | on-hand **right now** | any historical stock question |\n| Movement | `ls_inventory_logs` | dated stock ledger, aged inventory | unfiltered scans |\n\nA refund is **not** a separate record: it is a sale whose lines and payments are\nnegative, so `SUM(calc_total)` already nets refunds out. Layaway money moves on the\ntender date; the sale is recognised at `ls_sales.complete_time`. Takings and revenue\nwill never tie for a shop offering layaway — that is correct, not a bug.\n\n---\n\n## 4. Names: turning shop language into ids\n\n**The category tree is the tool for product-type questions.** `ls_categories` has\n`name` and `full_path_name` (79 nodes, slash-delimited, e.g.\n`Clothing & Protection/Eyewear`). Items attach to **one** node at any depth, so roll a\nbranch up with `full_path_name LIKE 'Parent/%' OR full_path_name = 'Parent'`. Leaf names\ncollide across branches — group and display by `full_path_name`, never by `name` alone.\n\nLive examples of the gap between shop words and category names:\n\n- \"glasses\" / \"sunnies\" → `Clothing & Protection/Eyewear`\n- \"tyres\" → `Parts/Wheels & Tyres`\n- \"lights\" → `Electronics & Lights/Lights`\n- \"racks\" → `Accessories1/Racks & Panniers` (note the literal `1`) **and**\n  `Training & Transport/Car Racks` — two different things, ask or answer both\n- \"servicing\" → the `Services` and `Workshop/Service` branches, plus uncategorised\n  service items\n\nThere is no category name on the item row. `ls_items.name` and `ls_items.full_path_name`\nexist as columns but are **NULL for every item** — join `ls_categories` on\n`ls_items.category_id`.\n\n**`category_id = 0` means uncategorised, not category zero.** 91 stocked items and 12\nservice items sit there. Any `LEFT JOIN` on categories must expect it, and any\n\"uncategorised\" count must treat 0 as the bucket, not as a real node.\n\n**Services and labour.** This is a service-led shop and services live in the item\ncatalogue like any product. The reliable test is not the category — it is the tax class:\n`ls_items.tax_class->>'name' = 'Labor'` (or `->>'classType' = 'service'`).\n`item_type = 'non_inventory'` (57 items) is the supporting signal. Service items are\nscattered across the `Services` branch, `Workshop/Service`, and `category_id = 0`, so\ncategory alone under-counts service revenue.\n\n**Fuzzy service names have close, wrong neighbours.** \"Gen service\" resolves to\n`Service - General Service` (`item_id` 9) — but the catalogue also holds\n`Service - General and Detail`, `Service - General Non Geared`, `Service - General\nLabour`, `General Service - E-Bike + Firmware` and `General Service - E-Bike (no\nfirmware)`. When several peers match, either aggregate them all and say you did, or\nname the one you picked in the answer. Do not silently take the top match.\n\n**`item_id = 0` is \"no catalogue item\", not item zero.** 22,722 sale lines carry it —\nmiscellaneous charges and some labour. Product rankings must exclude `item_id = 0` (not\n`IS NULL`, which matches nothing) or an unnamed bucket tops the chart.\n\n**Other zero-as-null fields.** Lightspeed writes `0` rather than null into unset foreign\nkeys throughout: `customer_id` on walk-in sales (38,072 of them — collapsing them gives\none phantom mega-customer), `manufacturer_id`, `item_matrix_id`, `employee_id`,\n`register_id`, `sale_id` on workorders. Treat 0 as absent everywhere.\n\n**Brands are not suppliers.** `ls_manufacturers` is who makes it; `ls_vendors` is who\nyou buy it from. An item has one manufacturer and can have many vendors. Brand casing is\ninconsistent in real data — `UPPER(TRIM(name))` before grouping.\n\n**Variants.** Every colour and size is its own `ls_items` row. \"How many products do we\nsell\" is rarely `COUNT(*)`: it is standalone items plus distinct `item_matrix_id`\nfamilies.\n\n---\n\n## 5. What is actually populated here\n\nAnswering \"no results\" when a table was simply never synced is worse than saying the\ndata is not available. Verified at this shop, counted **after** the Gate 2 dedupe — the\nraw row counts are roughly double these.\n\n**Rich:** `ls_inventory_logs` (127k), `ls_sale_lines` (116k),\n`ls_sale_payments` (53k), `ls_item_shops` (34k),\n`ls_sales` (61,197 tickets, 48,288 completed and unvoided, April 2018 → today),\n`ls_workorder_lines` / `ls_workorder_items` (~24.6k each),\n`ls_register_count_amounts` (19k), `ls_items` (17k), `ls_serialized` (16k),\n`ls_customers` (9.4k), `ls_catalog_vendor_items` (6.3k),\n`ls_purchase_orders` / `_lines` (~4.2k each).\n\n**Small but real:** 1 shop (Ashburton Cycles, `Australia/Sydney`, workshop rate $80),\n1 register, 9 employees, 9 payment types (Cash, Check, Credit Card, Credit Account,\nGift Card, Debit Card, eCom, Adjustment, PROMO GIFT CARD), 13 workorder statuses,\n79 categories, 34 discount rules, 21 voids.\n\n**Empty — say \"not available\", never \"zero\":** `ls_workorders` (**3 rows only**, while\nits lines and items tables are full — the job board itself is effectively unavailable,\nso answer workshop questions from `ls_sale_lines.is_workorder` instead),\n`ls_item_prices` and `ls_items.amount_where_use_type_default` / `_msrp`\n(**no selling price is staged at all** — price questions can only be answered from what\nwas actually charged, `ls_sale_lines.unit_price`), `ls_employee_hours` (this shop does\nnot use the built-in time clock), `ls_cc_charges` and `ls_processing_fees` (external\nEFTPOS terminal, so gateway and card-fee data never reach Lightspeed — read tenders from\n`payment_type_id` instead), `ls_transfers`, `ls_order_shipments`, `ls_vendor_returns`,\n`ls_account`, and all five `ls_report_*_by_day` tables.\n\nBecause the daily accounting reports are empty, tender mix, daily tax and daily\ndiscounts must be computed from raw sales and payments.\n\n---\n\n## 6. Cross-cutting traps\n\n- **Un-deduplicated pack versions.** §1. The number looks plausible and is exactly\n  double.\n- **\"Order\" means purchase order.** Answering \"how many orders last month\" from\n  `ls_purchase_orders` is the single most common wrong answer against this API.\n  Customer demand is `ls_sales`.\n- **Dates that look interchangeable.** Revenue is `ls_sales.complete_time`.\n  `create_time` is when the ticket opened; `updatetime` moves whenever anything is\n  touched; `time_stamp` changes meaning depending on `completed`. Only `complete_time`\n  is the trading date.\n- **Timezone.** The shop is `Australia/Sydney`. Bucket by\n  `complete_time AT TIME ZONE 'Australia/Sydney'` or days shift and yesterday's total\n  changes overnight.\n- **Archiving is the delete.** Items, customers, discounts and vendors are archived, not\n  removed, and history keeps referencing them — filtering `archived = false` in a\n  historical report deletes the history rather than excluding inactive records.\n- **Column names are the live staging names.** The dictionary in this prompt is\n  generated from the live DDL — trust it. Staging uses the vendor field name in\n  snake_case: `time_stamp` for last-modified, `create_time` for created, no `*_json`\n  suffix on embedded objects, and boolean flags keep their bare vendor name\n  (`complete`, `sent`, `open`).\n\n---\n\n## 7. What Lightspeed cannot tell you\n\nSay so plainly rather than deriving a number that looks right:\n\n- **Wages and labour cost.** No pay rate, salary, hire or termination date exists\n  anywhere in the API. `ls_shops.service_rate` ($80) is what the shop *charges*, not\n  what it pays. Never multiply hours by it.\n- **Stock as at a past date.** `ls_item_shops` is a live snapshot. A historical position\n  can only be reconstructed by running `ls_inventory_logs` backwards, and it will not\n  tie if items were archived or levels bulk-imported.\n- **Price history.** No record of what anything used to cost or sell for. Current\n  selling price is not even staged here (§5) — only what was charged on past lines.\n- **Workshop board history.** Status is overwritten in place; \"how many jobs were open\n  at the end of last month\" needs a snapshot nobody took.\n- **Turnaround time.** There is no completed-at on a job. The defensible proxy is the\n  linked sale's completion time.\n- **Card brand mix, gateway outcomes, processing fees.** External terminal; not in this\n  data at all.\n- **Profit after expenses, BAS, payroll.** That is Xero's half of the business."
});

/**
 * Per-dimension deep guides (money semantics, traps, worked SQL shapes),
 * injected by intent domain and on demand via open_dimension_guide.
 */
export const CONNECTOR_DIMENSION_GUIDES: Readonly<Record<string, Readonly<Record<string, string>>>> = Object.freeze({
  "lightspeed-r": {
    "customers": "# Customers dimension — who buys, repeat business, credit, marketing reach\n\nPrimary tables: `ls_customers` · `ls_contacts` (address + marketing flags) ·\n`ls_contact_emails` / `_phones` / `_websites` · `ls_customer_types` ·\n`ls_credit_accounts` · `ls_customer_notes` · `ls_ship_tos` · the custom-field trio.\nSpend questions join `ls_sales.customer_id`.\n\n## Customer rules\n\n- **Walk-ins dominate.** `ls_sales.customer_id = 0` on 38,072 sales — no customer was\n  attached. Any per-customer metric covers identified customers only; **say so** in the\n  answer. Never collapse the zeros into one phantom mega-customer.\n- **Duplicate identities are normal.** Till, webstore and workshop each create their own\n  row for the same human. Lifetime-value and repeat-rate answers cover identified,\n  possibly-duplicated customers; disclose it.\n- **Names:** `first_name` + `last_name` on `ls_customers` (no `full_name` column).\n  Contact detail lives on `ls_contacts` joined via `contact_id`, with emails and phones\n  in their own child tables (a customer can have several of each).\n- **Marketing flags are negatives.** `no_email = true` means *do not email*. A\n  reachable-by-email list must join `ls_contact_emails` AND check the opt-out flags on\n  `ls_contacts`.\n- **Store credit and gift cards** live on `ls_credit_accounts` (2,563 rows). Balance\n  sign convention: on a Credit Account tender, positive **debits** the account,\n  negative **deposits** to it.\n- **Customer segments** are `ls_customer_types` (only 2 at this shop) via\n  `customer_type_id`.\n- **Archived customers** keep their history; exclude them only for \"current customer\"\n  lists, never from historical spend.\n\n## Worked shape\n\n\"Who are our best customers this year\":\n\n```sql\nWITH pack AS (\n  SELECT mapping_version AS mv FROM source_lightspeed.ls_sales\n  GROUP BY 1 ORDER BY max(ingested_at) DESC LIMIT 1\n)\nSELECT c.customer_id,\n       c.first_name || ' ' || c.last_name AS customer,\n       COUNT(*)          AS tickets,\n       SUM(s.calc_total) AS spend_inc_gst\nFROM source_lightspeed.ls_sales s\nJOIN source_lightspeed.ls_customers c ON c.customer_id = s.customer_id\n  AND c.mapping_version = (SELECT mv FROM pack) AND NOT c.tombstone\nWHERE s.mapping_version = (SELECT mv FROM pack) AND NOT s.tombstone\n  AND s.completed AND NOT s.voided\n  AND s.customer_id <> 0\n  AND s.complete_time >= date_trunc('year', now() AT TIME ZONE 'Australia/Sydney')\nGROUP BY 1, 2\nORDER BY spend_inc_gst DESC\nLIMIT 20;\n```\n\nDisclose: *\"Covers sales with a customer attached — walk-in sales have no customer\nrecorded.\"*",
    "employees": "# Employees & registers dimension — staff, tills, cash control\n\nPrimary tables: `ls_employees` (+ roles/rights) · `ls_registers` ·\n`ls_register_counts` · `ls_register_count_amounts` · `ls_register_withdraws` ·\n`ls_sale_voids`. Performance questions join back to `ls_sales.employee_id`.\n\n## Employee rules\n\n- **Names:** `first_name` + `last_name` (no `full_name` column). 9 active employees at\n  this shop, 15 rows including departed staff — filter `archived = false` for the\n  current roster, keep archived rows for historical attribution.\n- **\"Who sold the most\"** is `ls_sales.employee_id` (who rang the ticket). Exclude\n  `employee_id = 0` (unattributed), never invent a \"House\" employee.\n- **Wages, pay rates, hours cost do not exist** anywhere in this data.\n  `ls_employee_hours` is empty (no time clock at this shop), and there is no pay rate\n  field in the API at all. Say so; never approximate from `ls_shops.service_rate`.\n- **Void-abuse check:** `ls_sale_voids` records who voided what — compare its\n  `employee_id` against the voided sale's own `employee_id`.\n\n## Register / cash rules\n\n- **Till sessions:** `ls_register_counts` (one row per open/close; `create_time` is the\n  close, `open_time` the open — not `closed_at`/`opened_at`).\n- **Over/short is `actual - calculated`** on `ls_register_count_amounts` (per tender\n  per session). Staff routinely skip counting card tenders, leaving `actual = 0`\n  against a large expected figure — a huge apparent card shortage almost always means\n  \"not counted\". Filter `actual <> 0` before ranking variances.\n- **Floats and payouts:** `ls_register_withdraws`.\n- **`ls_register_calculated`** (live drawer) is empty here — drawer questions use the\n  counts tables.\n\n## Worked shape\n\n\"Who sold the most this month\":\n\n```sql\nWITH pack AS (\n  SELECT mapping_version AS mv FROM source_lightspeed.ls_sales\n  GROUP BY 1 ORDER BY max(ingested_at) DESC LIMIT 1\n)\nSELECT e.first_name || ' ' || e.last_name AS employee,\n       COUNT(*)          AS tickets,\n       SUM(s.calc_total) AS sales_inc_gst\nFROM source_lightspeed.ls_sales s\nJOIN source_lightspeed.ls_employees e ON e.employee_id = s.employee_id\n  AND e.mapping_version = (SELECT mv FROM pack) AND NOT e.tombstone\nWHERE s.mapping_version = (SELECT mv FROM pack) AND NOT s.tombstone\n  AND s.completed AND NOT s.voided\n  AND s.employee_id <> 0\n  AND s.complete_time >= date_trunc('month', now() AT TIME ZONE 'Australia/Sydney')\nGROUP BY 1\nORDER BY sales_inc_gst DESC;\n```\n\nIf the owner asks about margin per person or profit per labour hour, that needs a\nconfirmed preference (`employee.net_sales` / `employee.gross_margin` /\n`employee.gross_profit_per_labour_hour`) — and labour-hour variants are unavailable\nwithout time-clock data.",
    "inventory": "# Inventory dimension — stock on hand, movement, ageing, stocktakes, catalogue\n\nPrimary tables: `ls_item_shops` (snapshot) · `ls_inventory_logs` (ledger) ·\n`ls_items` / `ls_categories` (catalogue) · stocktake trio (`ls_inventory_count_calcs`,\n`_items`, `_reconciles`) · `ls_special_orders` · `ls_serialized`.\n\n## Grain rules\n\n**Stock snapshot — `ls_item_shops`.** What is on the shelf **right now**. Overwritten in\nplace; there is no as-at date and no history. \"How much stock did we hold in March\" is\nunanswerable from it. Key columns: `item_id`, `shop_id`, `qoh`,\n`archived` (not `item_archived`), `time_stamp`. Whole-business stock uses\n`shop_id = 0`; never sum `shop_id = 0` with per-shop rows.\n\n**Names and costs are NOT on the stock row at this shop.** Verified live:\n`ls_item_shops.description` and `ls_item_shops.avg_cost` are NULL on every row.\nAlways join `ls_items` on `item_id` for the name (`i.description`) and the cost\n(`COALESCE(i.avg_cost, i.default_cost)`) — valuing stock from the snapshot's own\n`avg_cost` prices the whole shop at $0 and the report looks plausible but says\nnothing.\n\n**Movement — `ls_inventory_logs`.** The only dated stock ledger (~127k rows). Reach for\nit for \"where did the stock go\", shrinkage, receiving history, and **aged inventory**\n(days since last quantity movement, via `ls_inventory_logs.create_time`). Never scan it\nunfiltered — always bound by `item_id`, `shop_id` or a `create_time` range.\n\n## Inventory traps\n\n- **`ls_item_shops.shop_id = 0` is an all-shops rollup, not a shop.** Verified: 17,005\n  rollup rows and 17,005 real shop rows. Whole business → `shop_id = 0`. Per shop →\n  `shop_id > 0`. Never both in one aggregate.\n- **Stock value** is `qoh * COALESCE(i.avg_cost, i.default_cost)` (cost basis, from\n  the joined `ls_items` row — see above). There is no staged selling price\n  (`ls_item_prices` and `ls_items.amount_where_use_type_default` / `_msrp` are empty),\n  so retail-value questions can only use historical charged prices from\n  `ls_sale_lines.unit_price`, disclosed as such.\n- **Stocktakes:** `ls_inventory_count_calcs` is system-vs-counted, `_items` is each\n  counting act, `_reconciles` is the posted adjustment — **only the last one moves the\n  books**.\n- **`ls_serialized`** tracks bikes and frames by serial, but serials are often blank —\n  identity lives in `description`.\n- **`ls_special_orders`:** the follow-up list is `completed = false AND\n  contacted = false`.\n- **Archived items keep history.** Excluding `archived` rows is right for \"what do we\n  stock today\", wrong for historical movement reports.\n- **`ls_catalog_vendor_items`** is what suppliers *could* ship (not owned, not sold,\n  possibly a different currency). Never count it as stock.\n\n## Worked shape\n\n\"Give me an aged inventory report\" — on-hand stock aged by last movement. Use\n`ls_item_shops.archived` (never `item_archived`), `shop_id = 0` for the whole shop,\n`ls_inventory_logs.create_time` for age (never `created_at`), and join `ls_items`\nfor names and costs:\n\n```sql\nWITH pack AS (\n  SELECT mapping_version AS mv FROM source_lightspeed.ls_item_shops\n  GROUP BY 1 ORDER BY max(ingested_at) DESC LIMIT 1\n),\non_hand AS (\n  SELECT s.item_id, i.description, s.qoh,\n         COALESCE(i.avg_cost, i.default_cost, 0) AS unit_cost\n  FROM source_lightspeed.ls_item_shops s\n  JOIN source_lightspeed.ls_items i ON i.item_id = s.item_id\n    AND i.mapping_version = (SELECT mv FROM pack) AND NOT i.tombstone\n  WHERE s.mapping_version = (SELECT mv FROM pack)\n    AND NOT s.tombstone\n    AND s.shop_id = 0\n    AND NOT COALESCE(s.archived, false)\n    AND s.qoh <> 0\n),\nlast_move AS (\n  SELECT l.item_id, max(l.create_time) AS last_moved_at\n  FROM source_lightspeed.ls_inventory_logs l\n  WHERE l.mapping_version = (SELECT mv FROM pack)\n    AND NOT l.tombstone\n  GROUP BY 1\n)\nSELECT\n  CASE\n    WHEN m.last_moved_at IS NULL THEN 'No movement history'\n    WHEN m.last_moved_at >= now() - interval '30 days' THEN '0-30 days'\n    WHEN m.last_moved_at >= now() - interval '60 days' THEN '31-60 days'\n    WHEN m.last_moved_at >= now() - interval '90 days' THEN '61-90 days'\n    WHEN m.last_moved_at >= now() - interval '180 days' THEN '91-180 days'\n    ELSE '180+ days'\n  END AS age_band,\n  count(*) AS skus,\n  sum(o.qoh) AS units,\n  sum(o.qoh * o.unit_cost) AS stock_value\nFROM on_hand o\nLEFT JOIN last_move m ON m.item_id = o.item_id\nGROUP BY 1\nORDER BY min(coalesce(m.last_moved_at, '1970-01-01'::timestamptz));\n```\n\nThe bands alone are half a report. Follow with the detail cut in the same turn —\nthe stalest stock ranked by value tied up, so the owner knows *which* items are the\nproblem (reuse the same `pack`, `on_hand`, `last_move` CTEs):\n\n```sql\nSELECT o.description, o.qoh, o.unit_cost,\n       o.qoh * o.unit_cost AS stock_value,\n       m.last_moved_at::date AS last_movement\nFROM on_hand o\nLEFT JOIN last_move m ON m.item_id = o.item_id\nWHERE m.last_moved_at IS NULL OR m.last_moved_at < now() - interval '90 days'\nORDER BY o.qoh * o.unit_cost DESC\nLIMIT 25\n```\n\nThen answer as a report: headline (how much stock value is sitting in the stale\nbands), the band table, the stalest-items table, and what stands out.",
    "purchasing": "# Purchasing dimension — supplier orders, receiving, vendors\n\nPrimary tables: `ls_purchase_orders` · `ls_purchase_order_lines` · `ls_vendors` ·\n`ls_item_vendor_nums` (supplier SKUs and buy costs) · `ls_catalog_vendor_items`\n(supplier catalogues). `ls_order_shipments` / `_items` and `ls_vendor_returns` exist\nbut are **empty at this shop**.\n\n## Purchasing rules\n\n- **\"Orders\" from the owner almost never means POs** — customer demand is `ls_sales`.\n  Only \"on order\", \"ordered from <supplier>\", \"incoming stock\" mean purchasing.\n- **The PO id is `order_id`.** `ls_purchase_orders.order_id` is the primary key and\n  `ls_purchase_order_lines.order_id` is the join key (with `order_line_id` as the line\n  pk). There is no `purchase_order_id` column on either table.\n- **PO state:** `ls_purchase_orders.complete` (boolean, live name — not `is_complete`)\n  plus `archived`. Open POs: `complete = false AND NOT COALESCE(archived, false)`.\n  Dates: `ordered_date`, `received_date` (on the header).\n- **Line columns use vendor names:** `price` (unit buy cost), `original_price`,\n  `vendor_cost`, `checked_in`, `num_received`, `total` — not `unit_cost` /\n  `qty_checked_in` / `line_total` aliases.\n- **Parent-projected line columns are NULL.** `vendor_id`, `shop_id`, `complete`,\n  `ordered_date`, `received_date`, `archived` exist on `ls_purchase_order_lines` but\n  are unpopulated — join `ls_purchase_orders` on `order_id` for all of them.\n- **Vendor name** is `ls_purchase_orders.name` → prefer joining `ls_vendors` via\n  `vendor_id` for the canonical vendor row. Vendors are suppliers;\n  `ls_manufacturers` are brands. An item has one manufacturer, many possible vendors.\n- **Receiving history** at this shop is on `ls_inventory_logs` (the shipments tables\n  never synced) — a \"what arrived last week\" answer uses positive-quantity log entries,\n  disclosed as movement-based.\n- **`ls_catalog_vendor_items`** is what suppliers *could* ship — not owned, not on\n  order, possibly foreign currency. Never mix it into PO or stock figures.\n\n## Worked shape\n\n\"What's on order at the moment\":\n\n```sql\nWITH pack AS (\n  SELECT mapping_version AS mv FROM source_lightspeed.ls_purchase_orders\n  GROUP BY 1 ORDER BY max(ingested_at) DESC LIMIT 1\n)\nSELECT po.order_id,\n       COALESCE(v.name, po.name) AS vendor,\n       po.ordered_date,\n       po.total_quantity,\n       SUM(l.quantity)           AS units_on_lines,\n       SUM(l.quantity * l.price) AS order_value,\n       SUM(l.num_received)       AS units_received\nFROM source_lightspeed.ls_purchase_orders po\nLEFT JOIN source_lightspeed.ls_purchase_order_lines l ON l.order_id = po.order_id\n  AND l.mapping_version = (SELECT mv FROM pack) AND NOT l.tombstone\nLEFT JOIN source_lightspeed.ls_vendors v ON v.vendor_id = po.vendor_id\n  AND v.mapping_version = (SELECT mv FROM pack) AND NOT v.tombstone\nWHERE po.mapping_version = (SELECT mv FROM pack) AND NOT po.tombstone\n  AND po.complete = false\n  AND NOT COALESCE(po.archived, false)\nGROUP BY 1, 2, 3, 4\nORDER BY po.ordered_date DESC NULLS LAST;\n```\n\n**LEFT JOIN the lines, never inner-join:** verified live, the only open POs at this\nshop are three 2018–19 drafts whose lines were never staged — an inner join silently\ndrops them and \"what's on order\" comes back empty. When the open list is old drafts\nlike these, say the shop has nothing currently on order and name the stale drafts,\nrather than reporting zero.",
    "sales": "# Sales dimension — revenue, refunds, discounts, tenders, staff attribution\n\nPrimary tables: `ls_sales` (ticket) · `ls_sale_lines` (line) · `ls_sale_payments`\n(tender) · `ls_payment_types` · `ls_discounts` · `ls_sale_voids` · `ls_quotes` ·\n`ls_sale_accounts` (gift-card bridge). Category/product lookups join through\n`ls_items` → `ls_categories`.\n\n## Grain rules\n\n**Ticket — `ls_sales`.** One register transaction. Revenue, ticket counts, average\nbasket, margin at sale level, staff attribution, register and shop splits. A refund is\n**not** a separate record: it is a sale whose lines and payments are negative, so\n`SUM(calc_total)` already nets refunds out. Gross-before-refunds needs an explicit\n`calc_total > 0` split.\n\n**Line — `ls_sale_lines`.** One charge on one ticket. Everything per-product: units,\nrankings, per-item revenue, sell-through, returns. **This table carries no state of its\nown.** Its `completed` / `voided` / `complete_time` columns exist but are NULL in the\ncurrent pack generation. Every line-level revenue query must join `ls_sales` on\n`sale_id` and apply Gate 3 there, and date-filter on `ls_sales.complete_time`.\nThe line's own `create_time` is when the item went in the basket — on a layaway that\ncan be months early.\n\n**Tender — `ls_sale_payments`.** How money moved. This is takings, not revenue: a\nlayaway instalment or deposit lands on the day cash moved, while the sale is recognised\nat `complete_time`. They will never tie for a shop that offers layaway, and that is\ncorrect, not a bug. Filter `archived = false` — archived payments are reversed tenders\nand there are 4,072 of them here (about 8%), independent of whether the sale was voided.\nTender names come from `ls_payment_types.name` via `payment_type_id`.\n\n## Money: which column means what\n\n**Revenue at ticket level.** `calc_total` — grand total including GST, after discounts,\nwhat the POS displays. Four total columns exist and they disagree by design: `total` is\nan arithmetic restatement, `displayable_total` adds gift-card face value (double\ncounts), `total_due` subtracts gift-card and store-credit movement. Pick `calc_total`,\nstay with it, never mix them in one query.\n\n**Ex-GST.** At line level use `calc_total - calc_tax1 - calc_tax2`. Do **not** divide by\n1.1 and do **not** use the line's `calc_subtotal`: verified live, line `calc_subtotal` is\n*gross of the line discount* (a $99.99 line with $30 off carries `calc_total` 69.99,\n`calc_tax1` 6.36, `calc_subtotal` 93.63). At ticket level `ls_sales.calc_subtotal` is\nthe ex-tax figure and is safe.\n\n**Tax.** Money collected is `calc_tax1 + calc_tax2`. `tax1_rate` is a **fraction**\n(0.1 = 10%) and is only a default — any line with its own tax class overrides it, so\nnever reconstruct tax by multiplying. This shop runs two tax categories, \"Sales Tax\" and\n\"Labor Tax\", both 10% and both tax-inclusive.\n\n**Margin.** Gross profit = ex-GST revenue − FIFO cost. `calc_fifo_cost` is the basis\nLightspeed's own profit reports use; `calc_avg_cost` is the alternative. Pick one, never\nblend, never compare periods across bases. Cost columns are **ex-tax** while\n`calc_total` is **tax-inclusive** — pairing them overstates margin by roughly the GST\nrate. FIFO cost is 0 on service lines and on some migrated history, which silently\nreports 100% margin; fall back to `avg_cost` when FIFO is 0 and revenue is not, and say\nso.\n\n**Discounts.** `ls_sales.calc_discount` is total money given away, positive. At line\nlevel the full markdown is `calc_line_discount + calc_transaction_discount` — the first\nalone under-reports every whole-sale discount. `discount_percent` is a **fraction**\n(0.2 = 20%) everywhere it appears; reading it as a percent is the easiest 100× error in\nthis data. `ls_discounts.source_id` separates automatic price rules (0) from loyalty\nredemptions (1) from named manual rules (2); loyalty is the cost of a loyalty programme,\nnot a promotional markdown.\n\n**Refunds.** Negative `unit_quantity` at a **positive** `unit_price`. Never flip the\nprice sign. The reliable marker of a refund line is `parent_sale_line_id` being set, not\nthe sign alone (rebate lines are also negative). 787 negative-quantity lines exist.\n\n**Tips.** `tip_amount` sits **inside** `amount`, not on top. Merchandise money taken is\n`SUM(amount - tip_amount)`. Tips are not revenue.\n\n**Gift cards and store credit.** A gift card issue is a negative payment plus an\n`ls_sale_accounts` row; the later redemption is an ordinary positive payment on a\ndifferent sale. Counting both is double counting. On a Credit Account tender the sign\ninverts: positive **debits** the account, negative **deposits** to it.\n\n## Staff attribution\n\n\"Who sold the most\" is `ls_sales.employee_id` (who rang the ticket), joined to\n`ls_employees` (`first_name`, `last_name`). `employee_id = 0` means no attribution —\nexclude it, do not invent a \"House\" employee. `ls_sale_lines.employee_id` exists per\nline but is sparsely meaningful; ticket-level attribution is the honest default.\nVoid-abuse check: compare `ls_sale_voids.employee_id` (who voided) against the sale's\n`employee_id` (who rang it).\n\n## Quotes\n\nMeasure quote conversion from `ls_sales.quote_id`, never from `ls_quotes.sale_id`,\nwhich is reassigned on every edit.\n\n## Sales traps\n\n- **`ls_sale_lines.customer_id`** is populated only on layaway, special-order and\n  workorder lines. Grouping revenue by it drops nearly every ordinary sale and returns a\n  small, plausible, wrong number. The buyer is on the parent sale.\n- **`ls_sale_lines.avg_cost` / `fifo_cost` behave as line totals**, not per-unit costs,\n  despite the documentation. Multiplying by `unit_quantity` double counts COGS.\n- **Item-fee lines.** `item_fee_id` set means the row is a levy, not merchandise.\n  Counted as a product it inflates units and drags down average selling price.\n\n## Worked shapes\n\n\"Show a line graph of monthly sales\" — one aggregate, then chart. Do not probe\nwith `SELECT 1`, pack-only queries, or raw `complete_time` samples first:\n\n```sql\nWITH pack AS (\n  SELECT mapping_version AS mv FROM source_lightspeed.ls_sales\n  GROUP BY 1 ORDER BY max(ingested_at) DESC LIMIT 1\n)\nSELECT date_trunc('month', s.complete_time AT TIME ZONE 'Australia/Sydney') AS month,\n       SUM(s.calc_total) AS sales_inc_gst\nFROM source_lightspeed.ls_sales s\nWHERE s.mapping_version = (SELECT mv FROM pack)\n  AND NOT s.tombstone\n  AND s.completed\n  AND NOT s.voided\n  AND s.complete_time IS NOT NULL\nGROUP BY 1\nORDER BY 1;\n```\n\nThen `make_chart` with `chartType: \"line\"`, `xKey: \"month\"`, `yKey: \"sales_inc_gst\"`.\nAnswer in one sentence naming the period covered.\n\n\"Any glasses sold this year?\" — a product-type question, so category first:\n\n```sql\nWITH pack AS (\n  SELECT mapping_version AS mv FROM source_lightspeed.ls_sales\n  GROUP BY 1 ORDER BY max(ingested_at) DESC LIMIT 1\n)\nSELECT i.description,\n       SUM(l.unit_quantity)                                   AS units,\n       SUM(l.calc_total)                                      AS revenue_inc_gst,\n       SUM(l.calc_total - l.calc_tax1 - l.calc_tax2)           AS revenue_ex_gst\nFROM source_lightspeed.ls_sale_lines l\nJOIN source_lightspeed.ls_sales s   ON s.sale_id = l.sale_id  AND s.mapping_version = (SELECT mv FROM pack) AND NOT s.tombstone\nJOIN source_lightspeed.ls_items i   ON i.item_id = l.item_id   AND i.mapping_version = (SELECT mv FROM pack) AND NOT i.tombstone\nJOIN source_lightspeed.ls_categories c ON c.category_id = i.category_id AND c.mapping_version = (SELECT mv FROM pack) AND NOT c.tombstone\nWHERE l.mapping_version = (SELECT mv FROM pack) AND NOT l.tombstone\n  AND s.completed AND NOT s.voided\n  AND s.complete_time >= date_trunc('year', now() AT TIME ZONE 'Australia/Sydney')\n  AND (c.full_path_name = 'Clothing & Protection/Eyewear'\n       OR c.full_path_name LIKE 'Clothing & Protection/Eyewear/%')\nGROUP BY i.description\nORDER BY revenue_inc_gst DESC;\n```\n\nAnswer in one sentence with the number and the period, and name the assumption:\n*\"Treating glasses as the Eyewear category.\"* If it returns nothing, widen to an\n`ILIKE` on `i.description` across `'%glass%'`, `'%sunglass%'`, `'%eyewear%'` before\nconcluding there were none — and say which reading you used.\n\n\"What was our tender mix last month\" — payments, not sales:\n\n```sql\nWITH pack AS (\n  SELECT mapping_version AS mv FROM source_lightspeed.ls_sale_payments\n  GROUP BY 1 ORDER BY max(ingested_at) DESC LIMIT 1\n)\nSELECT pt.name AS tender,\n       SUM(p.amount - COALESCE(p.tip_amount, 0)) AS taken\nFROM source_lightspeed.ls_sale_payments p\nJOIN source_lightspeed.ls_sales s ON s.sale_id = p.sale_id\n  AND s.mapping_version = (SELECT mv FROM pack) AND NOT s.tombstone\n  AND s.completed AND NOT s.voided\nJOIN source_lightspeed.ls_payment_types pt ON pt.payment_type_id = p.payment_type_id\n  AND pt.mapping_version = (SELECT mv FROM pack) AND NOT pt.tombstone\nWHERE p.mapping_version = (SELECT mv FROM pack) AND NOT p.tombstone\n  AND NOT COALESCE(p.archived, false)\n  AND p.create_time >= date_trunc('month', now() AT TIME ZONE 'Australia/Sydney') - interval '1 month'\n  AND p.create_time <  date_trunc('month', now() AT TIME ZONE 'Australia/Sydney')\nGROUP BY 1\nORDER BY taken DESC;\n```\n\nDisclose that this is money taken (tender date), which differs from recognised revenue\nwhen layaways are involved.",
    "workshop": "# Workshop dimension — service revenue, the job board, labour\n\nPrimary tables: `ls_sale_lines` (with `is_workorder`) for **revenue** ·\n`ls_workorders` / `ls_workorder_lines` / `ls_workorder_items` /\n`ls_workorder_statuses` for the **job board** · `ls_serialized` for the bikes.\n\n## The one big fact\n\n**The job board itself is effectively unavailable at this shop.** `ls_workorders` has\n**3 rows only**, while `ls_workorder_lines` and `ls_workorder_items` are full (~24.6k\neach). \"How many jobs are open\" cannot be answered from the header table — say the\nboard is not synced rather than answering \"3\" or \"0\".\n\n**Recognised workshop revenue lives on sales**, not on workorders:\n`ls_sale_lines.is_workorder = true`, joined to `ls_sales` for Gate 3 state and\n`complete_time`. That is the honest default for \"how's the workshop going\", \"service\nrevenue\", \"how busy is the workshop\".\n\n## Workshop traps\n\n- **Workorder charges are quotes, not revenue.** Prices on `ls_workorder_lines` and\n  `ls_workorder_items` are job-sheet figures. Recognised workshop revenue is on the sale\n  created at checkout. Adding both double counts every completed job.\n- **Joining a workorder to both its lines and its items** multiplies rows (parts ×\n  labour). Aggregate each side in its own subquery.\n- **`ls_workorder_lines` has no total column.** Value is\n  `unit_price_override * unit_quantity`; where the override is 0 the charge was meant to\n  be hours × shop rate, and the rate is not in the data.\n- **Statuses are store-invented.** `ls_workorder_statuses` holds 13 statuses, 8 of them\n  custom (Quote, Non-Bike, TODAY, TO ORDER, VAN, Staff, Finished + Text Sent, Nest —\n  their `system_value` is NULL). Never filter on a guessed status name; read this table\n  first.\n- **No turnaround time exists.** There is no completed-at on a job. The defensible\n  proxy is the linked sale's completion time, and say it is a proxy.\n- **Labour cost is not in the data.** `ls_shops.service_rate` ($80) is what the shop\n  charges, not what it pays.\n\n## Worked shape\n\n\"How is the workshop going this month vs last month\":\n\n```sql\nWITH pack AS (\n  SELECT mapping_version AS mv FROM source_lightspeed.ls_sales\n  GROUP BY 1 ORDER BY max(ingested_at) DESC LIMIT 1\n)\nSELECT date_trunc('month', s.complete_time AT TIME ZONE 'Australia/Sydney') AS month,\n       SUM(l.calc_total)     AS workshop_revenue_inc_gst,\n       COUNT(DISTINCT s.sale_id) AS tickets_with_workshop\nFROM source_lightspeed.ls_sale_lines l\nJOIN source_lightspeed.ls_sales s ON s.sale_id = l.sale_id\n  AND s.mapping_version = (SELECT mv FROM pack) AND NOT s.tombstone\n  AND s.completed AND NOT s.voided\nWHERE l.mapping_version = (SELECT mv FROM pack) AND NOT l.tombstone\n  AND l.is_workorder = true\n  AND s.complete_time >= date_trunc('month', now() AT TIME ZONE 'Australia/Sydney') - interval '1 month'\nGROUP BY 1\nORDER BY 1;\n```\n\nDisclose the reading: *\"Counting items and labour rung up through workshop jobs.\"*"
  }
});

/** The always-injected core playbook for a connector, or "" when it ships none. */
export function connectorPlaybookCore(connectorId: string): string {
  return CONNECTOR_PLAYBOOK_CORES[connectorId] ?? "";
}

/** One dimension guide, or "" when the connector or guide does not exist. */
export function connectorDimensionGuide(connectorId: string, dimension: string): string {
  return CONNECTOR_DIMENSION_GUIDES[connectorId]?.[dimension] ?? "";
}

/** Guide names available for a connector. */
export function connectorDimensionGuideNames(connectorId: string): readonly string[] {
  return Object.freeze(Object.keys(CONNECTOR_DIMENSION_GUIDES[connectorId] ?? {}));
}
